{{
    config(
        materialized='table'
    )
}}

with sess as (
    select * from {{ ref('fct_session_quality') }}
), visitor_counts as (
    select visitor_id, count(*) as session_cnt, sum(case when is_converted then 1 else 0 end) as conv_cnt
    from sess
    group by visitor_id
), segmented as (
    select
        case
            when session_cnt >= 5 then 'Power User'
            when session_cnt >= 2 then 'Regular'
            else 'One-Time'
        end as visitor_segment,
        session_cnt,
        conv_cnt
    from visitor_counts
)
select
    visitor_segment,
    count(distinct visitor_id) as visitor_count,
    sum(session_cnt) as total_sessions,
    round(avg(session_cnt)::numeric, 2) as avg_sessions_per_visitor,
    sum(conv_cnt) as total_conversions,
    round(sum(conv_cnt)::numeric / nullif(sum(session_cnt),0), 4) as conversion_rate
from (
    select visitor_id, visitor_segment, session_cnt, conv_cnt from segmented
) s
group by visitor_segment

